"""Evaluate allergen and nutrition extraction against gold labels.

    # synthetic benchmark (generated by evaluation/synth/generate.py)
    python evaluation/evaluate.py synth --data data/synth_test --out evaluation/results/synth_test

    # private real-world set (PDFs identified by SHA-256 in real_labels.json)
    python evaluation/evaluate.py real --data /path/to/pdfs --out evaluation/results/real

Two systems are compared on exactly the same extracted text:

* ``v1``: this repository's engine (evidence rules + fusion + visual cell readers);
* ``legacy``: the v0.3 regex parser (10 allergens, defaults to "absent").

Metrics are defined in docs/method.md. The most important one is the
**unsafe miss rate**: the share of allergens that are in the product
(contains or traces) but were reported as absent.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import random
import sys
import time
from collections import Counter, defaultdict
from concurrent.futures import ProcessPoolExecutor
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
sys.path.insert(0, str(ROOT / "evaluation" / "baselines"))

from nutriparse.allergens import ALLERGENS, detect  # noqa: E402
from nutriparse.extraction import load  # noqa: E402
from nutriparse.metadata import is_non_food  # noqa: E402
from nutriparse.nutrition import parse_nutrition  # noqa: E402
from nutriparse.pipeline import nutrition_section  # noqa: E402
from nutriparse.text import for_nutrition, norm  # noqa: E402

STATUSES = ("contains", "traces", "absent", "unknown")
POSITIVE = {"contains", "traces"}
NUTRIENTS = ("energy_kJ", "energy_kcal", "fat_g", "saturated_fat_g", "carbohydrate_g",
             "sugars_g", "protein_g", "salt_g")


# ---------------------------------------------------------------------------
# Running the systems
# ---------------------------------------------------------------------------


def run_one(path: str) -> dict:
    from legacy_allergen_parser import parse_allergens as legacy_parse

    t0 = time.perf_counter()
    doc = load(path)
    raw = doc.text()
    ntext = norm(raw)
    if is_non_food(ntext):
        v1 = {a: "unknown" for a in ALLERGENS}
    else:
        v1 = {a: d.status for a, d in detect(doc).items()}
    seconds = time.perf_counter() - t0
    legacy_raw = legacy_parse(for_nutrition(raw))
    legacy = {a: (legacy_raw.get(a) or {}).get("status", "unknown") for a in ALLERGENS}
    values, _, _, _ = parse_nutrition(nutrition_section(for_nutrition(raw)))
    return {"v1": v1, "legacy": legacy, "nutrition": {k: values.get(k) for k in NUTRIENTS},
            "mode": doc.mode, "seconds": round(seconds, 2)}


def run_all(paths: list[str], workers: int) -> dict[str, dict]:
    out: dict[str, dict] = {}
    with ProcessPoolExecutor(max_workers=workers) as ex:
        for p, res in zip(paths, ex.map(run_one, paths), strict=True):
            out[p] = res
    return out


# ---------------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------------


def allergen_metrics(pairs: list[tuple[str, str]]) -> dict:
    """pairs: (gold, predicted) for every (document, allergen)."""
    n = len(pairs)
    cm = Counter(pairs)
    pos = [(g, p) for g, p in pairs if g in POSITIVE]
    known = [(g, p) for g, p in pairs if g != "unknown"]
    answered = [(g, p) for g, p in pairs if p != "unknown"]
    not_absent = [(g, p) for g, p in pairs if g != "absent"]

    def rate(xs, cond):
        return round(sum(1 for x in xs if cond(*x)) / len(xs), 4) if xs else None

    return {
        "n": n,
        "accuracy": rate(pairs, lambda g, p: g == p),
        "unsafe_miss_rate": rate(pos, lambda g, p: p == "absent"),
        "false_absent_rate": rate(not_absent, lambda g, p: p == "absent"),
        "positive_recall": rate(pos, lambda g, p: p in POSITIVE),
        "abstention_rate": rate(known, lambda g, p: p == "unknown"),
        "selective_accuracy": rate(answered, lambda g, p: g == p),
        "confusion": {g: {p: cm[(g, p)] for p in STATUSES} for g in STATUSES},
    }


def bootstrap(docs: list[list[tuple[str, str]]], metric: str, reps: int = 1000, seed: int = 0):
    """95% CI by resampling documents (allergens in a document are correlated)."""
    rng = random.Random(seed)
    vals = []
    for _ in range(reps):
        sample = [pair for _ in docs for pair in rng.choice(docs)]
        v = allergen_metrics(sample)[metric]
        if v is not None:
            vals.append(v)
    if not vals:
        return None
    vals.sort()
    return [round(vals[int(0.025 * len(vals))], 4), round(vals[int(0.975 * len(vals)) - 1], 4)]


def nutrition_metrics(rows: list[tuple[dict, dict]]) -> dict:
    """Share of nutrients extracted within 1% (or 0.05 g) of the truth."""
    per = {}
    for k in NUTRIENTS:
        ok = tot = found = 0
        for gold, pred in rows:
            if gold.get(k) is None:
                continue
            tot += 1
            p = pred.get(k)
            if isinstance(p, (int, float)):
                found += 1
                if abs(p - gold[k]) <= max(0.05, 0.01 * abs(gold[k])):
                    ok += 1
        per[k] = {"n": tot, "extracted": round(found / tot, 4) if tot else None,
                  "correct": round(ok / tot, 4) if tot else None}
    return per


# ---------------------------------------------------------------------------
# Datasets
# ---------------------------------------------------------------------------


def synth_items(data: Path) -> list[dict]:
    items = []
    for line in open(data / "labels.jsonl", encoding="utf-8"):
        rec = json.loads(line)
        for variant, fname in rec["files"].items():
            items.append({"id": rec["id"], "variant": variant, "format": rec["format"],
                          "language": rec["language"], "path": str(data / fname),
                          "gold": rec["allergens"], "nutrition": rec["nutrition"]})
    return items


def real_items(data: Path) -> list[dict]:
    labels = json.load(open(ROOT / "evaluation" / "real_labels.json", encoding="utf-8"))
    by_hash = {d["sha256"]: d for d in labels["documents"]}
    items = []
    for p in sorted(data.glob("*.pdf")):
        d = by_hash.get(hashlib.sha256(p.read_bytes()).hexdigest())
        if d is None:
            continue
        if d["default"] == "not_applicable":
            continue  # non-food sheet: allergens are not assessed
        gold = {a: d["labels"].get(a, d["default"]) for a in ALLERGENS}
        items.append({"id": d["id"], "variant": "scanned" if d["scanned"] else "digital",
                      "format": d["declaration_format"], "language": "-", "path": str(p),
                      "gold": gold, "nutrition": None})
    missing = len([d for d in labels["documents"] if d["default"] != "not_applicable"]) - len(items)
    if missing:
        print(f"warning: {missing} labelled documents not found in {data}")
    return items


# ---------------------------------------------------------------------------
# Report
# ---------------------------------------------------------------------------


def summarise(items: list[dict], results: dict[str, dict]) -> dict:
    report: dict = {"documents": len(items), "systems": {}}
    groups = {"all": items}
    for key in ("variant", "format"):
        for it in items:
            groups.setdefault(f"{key}={it[key]}", []).append(it)
    for system in ("v1", "legacy"):
        sysrep = {}
        for name, its in groups.items():
            docs = [[(it["gold"][a], results[it["path"]][system][a]) for a in ALLERGENS] for it in its]
            pairs = [x for d in docs for x in d]
            m = allergen_metrics(pairs)
            if name == "all" or name.startswith("variant="):
                m["ci95_unsafe_miss_rate"] = bootstrap(docs, "unsafe_miss_rate")
                m["ci95_accuracy"] = bootstrap(docs, "accuracy")
            sysrep[name] = m
        per_allergen = {}
        for a in ALLERGENS:
            pairs = [(it["gold"][a], results[it["path"]][system][a]) for it in items]
            m = allergen_metrics(pairs)
            per_allergen[a] = {k: m[k] for k in ("n", "accuracy", "unsafe_miss_rate", "positive_recall",
                                                 "abstention_rate")}
        sysrep["per_allergen"] = per_allergen
        report["systems"][system] = sysrep
    nut_rows = [(it["nutrition"], results[it["path"]]["nutrition"]) for it in items if it["nutrition"]]
    if nut_rows:
        report["nutrition"] = {}
        for variant in sorted({it["variant"] for it in items}):
            rows = [(it["nutrition"], results[it["path"]]["nutrition"]) for it in items
                    if it["nutrition"] and it["variant"] == variant]
            report["nutrition"][variant] = nutrition_metrics(rows)
    secs = [results[it["path"]]["seconds"] for it in items]
    by_mode = defaultdict(list)
    for it in items:
        by_mode[results[it["path"]]["mode"]].append(results[it["path"]]["seconds"])
    report["latency_seconds"] = {m: round(sorted(v)[len(v) // 2], 2) for m, v in by_mode.items()}
    report["latency_seconds"]["all_median"] = round(sorted(secs)[len(secs) // 2], 2)
    return report


def pct(x) -> str:
    return "n/a" if x is None else f"{100 * x:.1f}%"


def ci(x) -> str:
    return "" if not x else f" [{100 * x[0]:.1f}, {100 * x[1]:.1f}]"


def markdown(report: dict, title: str, errors: list[str]) -> str:
    L = [f"# {title}", "", f"Documents: {report['documents']} "
         f"(each scored on 14 allergens). 95% intervals: document bootstrap, 1000 resamples.", ""]
    L += ["## Headline", "", "| System | Accuracy | Unsafe miss rate | False absent rate | Positive recall | Abstention |",
          "|---|---|---|---|---|---|"]
    for s, rep in report["systems"].items():
        a = rep["all"]
        L.append(f"| {s} | {pct(a['accuracy'])}{ci(a.get('ci95_accuracy'))} | "
                 f"{pct(a['unsafe_miss_rate'])}{ci(a.get('ci95_unsafe_miss_rate'))} | "
                 f"{pct(a['false_absent_rate'])} | {pct(a['positive_recall'])} | {pct(a['abstention_rate'])} |")
    for key, label in (("variant=", "By input quality"), ("format=", "By declaration format")):
        L += ["", f"## {label}", "", "| Group | n | v1 accuracy | v1 unsafe miss | v1 abstention | legacy accuracy | legacy unsafe miss |",
              "|---|---|---|---|---|---|---|"]
        names = sorted(k for k in report["systems"]["v1"] if k.startswith(key))
        for nme in names:
            v, g = report["systems"]["v1"][nme], report["systems"]["legacy"][nme]
            L.append(f"| {nme[len(key):]} | {v['n'] // 14} | {pct(v['accuracy'])} | {pct(v['unsafe_miss_rate'])} | "
                     f"{pct(v['abstention_rate'])} | {pct(g['accuracy'])} | {pct(g['unsafe_miss_rate'])} |")
    L += ["", "## Per allergen (v1)", "", "| Allergen | Accuracy | Unsafe miss | Positive recall | Abstention |",
          "|---|---|---|---|---|"]
    for a, m in report["systems"]["v1"]["per_allergen"].items():
        L.append(f"| {a} | {pct(m['accuracy'])} | {pct(m['unsafe_miss_rate'])} | {pct(m['positive_recall'])} | "
                 f"{pct(m['abstention_rate'])} |")
    L += ["", "## Confusion matrix (v1, all)", "", "| gold \\ predicted | " + " | ".join(STATUSES) + " |",
          "|---" * (len(STATUSES) + 1) + "|"]
    cm = report["systems"]["v1"]["all"]["confusion"]
    for g in STATUSES:
        L.append(f"| {g} | " + " | ".join(str(cm[g][p]) for p in STATUSES) + " |")
    if "nutrition" in report:
        L += ["", "## Nutrition (share of values within 1% or 0.05 g)", "",
              "| Nutrient | " + " | ".join(report["nutrition"]) + " |", "|---" * (len(report["nutrition"]) + 1) + "|"]
        for k in NUTRIENTS:
            L.append(f"| {k} | " + " | ".join(pct(report["nutrition"][v][k]["correct"]) for v in report["nutrition"]) + " |")
    L += ["", "## Latency (median seconds per document, v1)", ""]
    for k, v in report["latency_seconds"].items():
        L.append(f"- {k}: {v}")
    if errors:
        L += ["", "## v1 errors (first 40)", "", "```"] + errors[:40] + ["```"]
    return "\n".join(L) + "\n"


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("dataset", choices=["synth", "real"])
    ap.add_argument("--data", type=Path, required=True)
    ap.add_argument("--out", type=Path, required=True)
    ap.add_argument("--workers", type=int, default=4)
    ap.add_argument("--variants", default="", help="comma list, e.g. digital,scan_good")
    args = ap.parse_args()

    items = synth_items(args.data) if args.dataset == "synth" else real_items(args.data)
    if args.variants:
        keep = set(args.variants.split(","))
        items = [it for it in items if it["variant"] in keep]
    paths = sorted({it["path"] for it in items})
    print(f"running {len(paths)} files with {args.workers} workers…", flush=True)
    t0 = time.time()
    results = run_all(paths, args.workers)
    print(f"done in {time.time() - t0:.0f}s")
    report = summarise(items, results)
    errors = []
    for it in items:
        r = results[it["path"]]["v1"]
        for a in ALLERGENS:
            if r[a] != it["gold"][a]:
                errors.append(f"{it['id']} {it['variant']:9} {it['format']:16} {it['language']} "
                              f"{a:12} gold={it['gold'][a]:8} pred={r[a]}")
    args.out.mkdir(parents=True, exist_ok=True)
    (args.out / "metrics.json").write_text(json.dumps(report, indent=2))
    (args.out / "predictions.json").write_text(json.dumps(
        {it["id"] + ":" + it["variant"]: results[it["path"]] for it in items}, indent=2))
    title = "Synthetic benchmark" if args.dataset == "synth" else "Real-world set (private PDFs)"
    (args.out / "REPORT.md").write_text(markdown(report, title, errors))
    a, b = report["systems"]["v1"]["all"], report["systems"]["legacy"]["all"]
    print(f"v1     accuracy {pct(a['accuracy'])}  unsafe miss {pct(a['unsafe_miss_rate'])}  abstention {pct(a['abstention_rate'])}")
    print(f"legacy accuracy {pct(b['accuracy'])}  unsafe miss {pct(b['unsafe_miss_rate'])}")
    print(f"{len(errors)} v1 errors; report in {args.out / 'REPORT.md'}")


if __name__ == "__main__":
    main()
